@namespace sv_3e1b4dac9929408db7c19e06a5695a32.Components.Pages.Settings
@using sv_3e1b4dac9929408db7c19e06a5695a32.Services

<div class="notifications-section">
    <h3>Notifications</h3>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-row">
                <input type="checkbox" @bind="_emailNotifications" />
                <span>Email Notifications</span>
            </label>
            <label class="toggle-row">
                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>
            <label class="toggle-row">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <div class="muted-channels">
            <h4>Muted Channels</h4>
            @foreach (var channel in _allChannels)
            {
                <label class="channel-row">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <button class="btn-primary" @onclick="SaveAsync">Save Preferences</button>

        @if (_showSuccess)
        {
            <div class="toast success">Preferences saved!</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _showSuccess;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    private static readonly string[] _allChannels = { "general", "marketing", "announcements", "engineering", "design" };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.notifications-section h3 {
    margin-bottom: 1.5rem;
    font-size: 1.4rem;
    color: #1a1a1a;
}

.toggle-group {
    margin-bottom: 2rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.6rem 0;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1565c0;
}

.muted-channels {
    margin-bottom: 1.5rem;
}

.muted-channels h4 {
    margin-bottom: 0.75rem;
    font-size: 1rem;
    color: #333;
}

.channel-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.4rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-row input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: #e65100;
}

.btn-primary {
    padding: 0.6rem 1.25rem;
    background: #1565c0;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #0d47a1;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

