    margin-bottom: 0.5rem;
}

.success-text {
    color: #2e7d32;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.tfa-section {
    margin-bottom: 2rem;
}

.tfa-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
}

.status-badge {
    display: inline-block;
    margin-left: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 500;
}

.status-badge.enabled {
    background: #e8f5e9;
