toolArgs.file_text:
.security-section h3 {
    margin-bottom: 1.5rem;
    font-size: 1.4rem;
    color: #1a1a1a;
}

.panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.9rem 1.25rem;
    background: #f8f9fa;
    cursor: pointer;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    color: #666;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-size: 0.9rem;
    font-weight: 500;
    color: #333;
}

.form-group input {
    width: 100%;
    max-width: 320px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.9rem;
}

.error-text {
    color: #c62828;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.success-text {
    color: #2e7d32;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.tfa-section {
    margin-bottom: 2rem;
}

.tfa-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
}

.status-badge {
    display: inline-block;
    margin-left: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 500;
}

.status-badge.enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-badge.disabled {
    background: #fbe9e7;
    color: #c62828;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    border-radius: 24px;
    transition: 0.3s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    border-radius: 50%;
    transition: 0.3s;
}

.toggle-switch input:checked + .slider {
    background-color: #1565c0;
}

.toggle-switch input:checked + .slider::before {
    transform: translateX(20px);
}

.meta-text {
    font-size: 0.85rem;
    color: #666;
}

.sessions-section h4 {
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 500;
    color: #555;
}

.btn-danger-sm {
    padding: 0.3rem 0.7rem;
    background: #ef5350;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
}

.btn-danger-sm:hover {
    background: #c62828;
}

.current-badge {
    font-size: 0.8rem;
    color: #1565c0;
    font-weight: 500;
}

.dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 10px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.dialog h4 {
    margin-bottom: 0.75rem;
}

.dialog p {
    margin-bottom: 1.25rem;
    color: #555;
    font-size: 0.95rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
}

.btn-danger {
    padding: 0.6rem 1.25rem;
    background: #ef5350;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-secondary {
    padding: 0.6rem 1.25rem;
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary {
    padding: 0.6rem 1.25rem;
    background: #1565c0;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #0d47a1;
}

