@namespace sv_3e1b4dac9929408db7c19e06a5695a32.Components.Pages.Settings
@using sv_3e1b4dac9929408db7c19e06a5695a32.Services

<div class="appearance-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Theme -->
        <div class="setting-group">
            <h4>Theme</h4>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-option">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="setting-group">
            <h4>Font Size</h4>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="setting-group">
            <h4>Language</h4>
            <select @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="setting-group">
            <label class="toggle-row">
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <div class="preview-header">Live Preview</div>
            <div class="preview-content">
                <p class="preview-title">Sample Heading</p>
                <p class="preview-text">This is how your content will look with the selected appearance settings. The theme, font size, and compact mode are reflected here.</p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <button class="btn-primary" @onclick="SaveAsync">Save</button>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _showSuccess;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-section h3 {
    margin-bottom: 1.5rem;
    font-size: 1.4rem;
    color: #1a1a1a;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.setting-group h4 {
    margin-bottom: 0.5rem;
    font-size: 1rem;
    color: #333;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.radio-option input[type="radio"] {
    accent-color: #1565c0;
}

.setting-group select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    min-width: 180px;
}

.toggle-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1565c0;
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 10px;
    padding: 1.25rem;
    margin-bottom: 1.5rem;
    transition: all 0.3s ease;
}

.preview-header {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #888;
    margin-bottom: 0.75rem;
}

.preview-title {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    line-height: 1.5;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 5px;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
}

/* Theme variants */
.preview-area.theme-light {
    background: #ffffff;
    color: #1a1a1a;
}

.preview-area.theme-light .preview-button {
    background: #1565c0;
    color: white;
}

.preview-area.theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-button {
    background: #64b5f6;
    color: #1e1e2e;
}

.preview-area.theme-dark .preview-header {
    color: #aaa;
}

.preview-area.theme-system {
    background: #f5f5f5;
    color: #333;
}

.preview-area.theme-system .preview-button {
    background: #455a64;
    color: white;
}

/* Font size variants */
.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-small .preview-title {
    font-size: 1rem;
}

.preview-area.font-medium {
    font-size: 0.95rem;
}

.preview-area.font-medium .preview-title {
    font-size: 1.2rem;
}

.preview-area.font-large {
    font-size: 1.1rem;
}

.preview-area.font-large .preview-title {
    font-size: 1.4rem;
}

/* Compact mode */
.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-area.compact .preview-title {
    margin-bottom: 0.25rem;
}

.preview-area.compact .preview-text {
    margin-bottom: 0.4rem;
}

.btn-primary {
    padding: 0.6rem 1.25rem;
    background: #1565c0;
    color: white;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #0d47a1;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

